SELECT fn_cp_import_case('vuln-personne-sans-domicile-refus-d-aide', '{"slug": "vuln-personne-sans-domicile-refus-d-aide", "title": "Il refuse la maraude pour la troisième nuit consécutive", "theme_slug": "personnes-vulnerables", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 23 heures, il fait moins deux degrés. Dans un porche d''immeuble, vous retrouvez une personne sans domicile qui refuse pour la troisième nuit consécutive la prise en charge proposée par la maraude, cette situation créant une tension entre l''autonomie de cette personne et le risque vital que fait peser ce froid intense sur sa santé. Cette configuration, où ce refus répété et assumé d''une aide pourtant disponible ne relève d''aucune incapacité de discernement manifeste, nécessite de respecter ce refus tout en réévaluant en permanence le risque vital que cette situation continue de faire peser sur cette personne.\n\nCette situation, caractéristique des tensions qui peuvent naître entre l''autonomie d''une personne en situation de rue et l''obligation de protection qui s''impose face à un risque vital avéré, impose une vigilance particulière qui ne bascule vers une action contraignante que si ce risque devient réellement imminent.\n\nCette configuration nécessite de respecter ce refus tout en réévaluant ce risque vital, cette double exigence restant essentielle pour concilier le respect de l''autonomie de cette personne avec la protection de sa vie face à ce froid intense.", "questions": [{"position": 1, "max_points": 5, "label": "Comment respectez-vous ce refus tout en évaluant le risque vital que ce froid fait peser sur cette personne ?", "hint": "Ce respect doit rester réel, cette exigence restant essentielle pour ne pas imposer une prise en charge à une personne qui la refuse tant que son discernement reste manifestement intact.", "perfect": "Je respecte ce refus exprimé par cette personne, cette autonomie restant essentielle tant qu''aucune incapacité de discernement n''est manifeste.\n\nJe reste factuelle dans l''évaluation de son état physique, cette observation restant essentielle pour détecter tout signe d''hypothermie ou de détresse qui changerait cette appréciation.\n\nJe reste attentive à lui rappeler les risques réels de ce froid intense, cette information restant utile pour qu''elle prenne sa décision en toute connaissance de cause.\n\nJe reste attentive à sa situation tout au long de cette patrouille, cette vigilance restant nécessaire pour réévaluer ce risque si son état venait à se dégrader.", "points": [{"position": 1, "label": "Respecter ce refus tant qu''aucune incapacité de discernement n''est manifeste", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : autonomie respectée sans incapacité manifeste.", "groups": [{"position": 1, "keywords": ["refus respecté", "discernement intact", "autonomie préservée"]}]}, {"position": 2, "label": "Évaluer factuellement son état physique pour détecter des signes d''hypothermie", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Observation détectant tout changement d''appréciation.", "groups": [{"position": 1, "keywords": ["état évalué", "hypothermie recherchée", "signes détectés"]}]}, {"position": 3, "label": "Rappeler les risques réels de ce froid intense", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Décision éclairée de la personne concernée.", "groups": [{"position": 1, "keywords": ["risques rappelés", "décision éclairée", "froid signalé"]}]}, {"position": 4, "label": "Rester attentive à sa situation tout au long de la patrouille", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réévaluation continue du risque vital.", "groups": [{"position": 1, "keywords": ["vigilance maintenue", "situation suivie", "risque réévalué"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment sollicitez-vous à nouveau la maraude malgré ces refus déjà exprimés à trois reprises ?", "hint": "Cette sollicitation renouvelée doit rester adaptée, cette persévérance restant utile pour ne pas abandonner cette personne tout en respectant son autonomie déjà exprimée à plusieurs reprises.", "perfect": "Je sollicite à nouveau la maraude compétente pour cette personne, cette persévérance restant utile malgré ces refus déjà exprimés à trois reprises.\n\nJe reste factuelle sur l''évolution de la situation météorologique, cette information restant utile pour que la maraude ajuste son approche envers cette personne.\n\nJe reste attentive à ne pas culpabiliser cette personne pour ces refus répétés, cette réserve restant appropriée pour préserver la relation de confiance nécessaire.\n\nJe reste attentive à proposer des alternatives partielles, comme une couverture supplémentaire, si un hébergement complet continue d''être refusé.", "points": [{"position": 1, "label": "Solliciter à nouveau la maraude compétente malgré ces refus antérieurs", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : persévérance malgré les refus répétés.", "groups": [{"position": 1, "keywords": ["maraude sollicitée", "refus antérieurs", "persévérance appliquée"]}]}, {"position": 2, "label": "Informer sur l''évolution de la situation météorologique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ajustement de l''approche de la maraude.", "groups": [{"position": 1, "keywords": ["météo signalée", "approche ajustée", "maraude informée"]}]}, {"position": 3, "label": "Ne pas culpabiliser cette personne pour ces refus répétés", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Relation de confiance préservée.", "groups": [{"position": 1, "keywords": ["culpabilisation évitée", "confiance préservée", "réserve appliquée"]}]}, {"position": 4, "label": "Proposer des alternatives partielles si l''hébergement complet est refusé", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Solutions partielles en cas de refus persistant.", "groups": [{"position": 1, "keywords": ["alternative proposée", "couverture fournie", "refus persistant"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment basculez-vous vers une action plus contraignante si ce risque vital devenait réellement imminent ?", "hint": "Ce basculement doit rester proportionné, cette exigence restant essentielle pour n''intervenir de manière contraignante que si le risque vital devient réellement imminent au regard de l''état constaté de cette personne.", "perfect": "Je reste attentive aux signes d''un risque vital réellement imminent, cette vigilance restant essentielle pour déterminer le moment d''une action plus contraignante.\n\nJe reste factuelle sur les éléments qui caractériseraient ce risque imminent, cette précision restant utile pour justifier une intervention si elle devenait nécessaire.\n\nJe reste attentive à solliciter les secours médicaux compétents si cet état de santé le justifiait, cette sollicitation restant proportionnée à la gravité constatée.\n\nJe reste attentive à documenter précisément l''évolution de cette situation, cette traçabilité restant utile pour la suite de cette procédure.", "points": [{"position": 1, "label": "Rester attentive aux signes d''un risque vital réellement imminent", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vigilance déterminant le moment d''agir.", "groups": [{"position": 1, "keywords": ["risque imminent", "signes surveillés", "moment déterminé"]}]}, {"position": 2, "label": "Identifier factuellement les éléments caractérisant ce risque imminent", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Précision justifiant une intervention nécessaire.", "groups": [{"position": 1, "keywords": ["éléments identifiés", "risque caractérisé", "intervention justifiée"]}]}, {"position": 3, "label": "Solliciter les secours médicaux compétents si l''état de santé le justifie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Sollicitation proportionnée à la gravité constatée.", "groups": [{"position": 1, "keywords": ["secours sollicités", "gravité constatée", "proportionnalité assurée"]}]}, {"position": 4, "label": "Documenter précisément l''évolution de cette situation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Traçabilité pour la suite de la procédure.", "groups": [{"position": 1, "keywords": ["situation documentée", "évolution tracée", "procédure suivie"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('vuln-personne-handicapee-victime-de-vol', '{"slug": "vuln-personne-handicapee-victime-de-vol", "title": "Son fauteuil a été renversé pour lui prendre son sac", "theme_slug": "personnes-vulnerables", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 17 heures. À un arrêt de bus, une personne en fauteuil roulant vous signale qu''elle a été victime d''un vol avec violence, son fauteuil ayant été renversé par l''auteur pour lui subtiliser son sac, cette vulnérabilité aggravante ayant rendu impossible toute défense ou fuite de sa part. Cette configuration, où ce handicap moteur combiné à cette atteinte aux biens commise avec violence caractérise une situation particulièrement éprouvante pour cette victime, nécessite d''adapter votre accueil et votre prise en charge à ce handicap tout au long de cette intervention.\n\nCette situation, caractéristique des vols avec violence qui peuvent viser des personnes en situation de handicap incapables de se défendre ou de fuir, impose une prise en charge attentive qui tienne compte à la fois du choc de cette agression et des besoins spécifiques liés à ce handicap moteur.\n\nCette configuration nécessite d''adapter l''accueil et la prise en charge à ce handicap, cette exigence restant essentielle pour traiter cette victime avec la dignité et l''attention que sa situation particulière requiert.", "questions": [{"position": 1, "max_points": 5, "label": "Comment adaptez-vous votre accueil et votre prise en charge à ce handicap moteur ?", "hint": "Cette adaptation doit rester concrète, cette exigence restant essentielle pour traiter cette victime avec l''attention particulière que requiert ce handicap moteur dans le contexte de cette agression.", "perfect": "Je m''assure d''abord que cette personne n''est pas blessée par ce renversement de son fauteuil, cette vérification restant prioritaire avant tout autre acte.\n\nJe reste factuelle et attentive à sa hauteur pour cet échange, cette adaptation posturale restant appropriée pour cette communication avec une personne en fauteuil.\n\nJe reste attentive à l''aider à se repositionner correctement dans son fauteuil si nécessaire, cette assistance restant appropriée compte tenu de ce handicap.\n\nJe reste attentive à ne pas la traiter différemment dans le fond de mon recueil, cette égalité de traitement restant essentielle malgré cette adaptation de forme nécessaire.", "points": [{"position": 1, "label": "S''assurer d''abord qu''elle n''est pas blessée par ce renversement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vérification prioritaire de l''état physique.", "groups": [{"position": 1, "keywords": ["blessure vérifiée", "priorité assurée", "état physique"]}]}, {"position": 2, "label": "Rester attentive à sa hauteur pour cet échange", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Adaptation posturale appropriée pour la communication.", "groups": [{"position": 1, "keywords": ["hauteur adaptée", "communication facilitée", "posture appropriée"]}]}, {"position": 3, "label": "L''aider à se repositionner correctement dans son fauteuil si nécessaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Assistance appropriée compte tenu du handicap.", "groups": [{"position": 1, "keywords": ["repositionnement aidé", "fauteuil ajusté", "assistance apportée"]}]}, {"position": 4, "label": "Ne pas la traiter différemment dans le fond de son recueil", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Égalité de traitement malgré l''adaptation de forme.", "groups": [{"position": 1, "keywords": ["égalité assurée", "recueil identique", "traitement équitable"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous les éléments de ce vol avec violence commis sur cette personne vulnérable ?", "hint": "Ce recueil doit rester complet et précis, cette rigueur restant essentielle pour caractériser correctement cette circonstance aggravante liée à cette vulnérabilité particulière de la victime.", "perfect": "Je recueille précisément les circonstances de ce vol, notamment le renversement de ce fauteuil qui caractérise une violence aggravée par cette vulnérabilité.\n\nJe reste factuelle sur le signalement de l''auteur donné par cette victime, cette précision restant utile pour orienter d''éventuelles recherches.\n\nJe reste attentive à recueillir les préjudices tant matériels que moraux subis par cette victime du fait de cette agression particulièrement éprouvante.\n\nJe reste attentive à l''informer de ses droits en tant que victime, notamment ceux liés à cette circonstance aggravante de vulnérabilité.", "points": [{"position": 1, "label": "Recueillir précisément les circonstances de ce vol avec violence aggravée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : caractérisation de la vulnérabilité aggravante.", "groups": [{"position": 1, "keywords": ["circonstances recueillies", "violence aggravée", "vulnérabilité caractérisée"]}]}, {"position": 2, "label": "Recueillir factuellement le signalement de l''auteur", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Précision orientant d''éventuelles recherches.", "groups": [{"position": 1, "keywords": ["auteur signalé", "recherches orientées", "signalement précisé"]}]}, {"position": 3, "label": "Recueillir les préjudices matériels et moraux subis", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Préjudices précisément documentés.", "groups": [{"position": 1, "keywords": ["préjudices recueillis", "victime entendue", "agression documentée"]}]}, {"position": 4, "label": "Informer des droits liés à cette circonstance aggravante de vulnérabilité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Droits spécifiques liés à cette vulnérabilité.", "groups": [{"position": 1, "keywords": ["droits informés", "vulnérabilité reconnue", "victime éclairée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment accompagnez-vous cette victime au-delà du recueil de cette plainte ?", "hint": "Cet accompagnement doit rester attentif, cette démarche restant utile pour prendre soin de cette victime au-delà du strict recueil de cette plainte compte tenu de sa vulnérabilité particulière.", "perfect": "Je reste attentive à m''assurer que cette personne peut rentrer chez elle en sécurité après cette agression, cette vérification restant appropriée compte tenu de ce choc subi.\n\nJe reste factuelle et rassurante dans mes échanges avec elle, cette approche restant appropriée pour l''aider à surmonter ce moment difficile.\n\nJe reste attentive à l''orienter vers des associations d''aide aux victimes adaptées à sa situation de handicap si elle le souhaite.\n\nJe reste disponible pour la recontacter si des éléments nouveaux apparaissaient dans cette enquête, cette disponibilité restant rassurante pour elle.", "points": [{"position": 1, "label": "S''assurer qu''elle peut rentrer chez elle en sécurité après cette agression", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : sécurité assurée après ce choc subi.", "groups": [{"position": 1, "keywords": ["retour sécurisé", "sécurité vérifiée", "choc pris en compte"]}]}, {"position": 2, "label": "Rester factuelle et rassurante dans ses échanges", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Approche appropriée pour surmonter ce moment difficile.", "groups": [{"position": 1, "keywords": ["attitude rassurante", "moment difficile", "approche appropriée"]}]}, {"position": 3, "label": "L''orienter vers des associations d''aide aux victimes adaptées", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Orientation adaptée à sa situation de handicap.", "groups": [{"position": 1, "keywords": ["association orientée", "aide adaptée", "handicap pris en compte"]}]}, {"position": 4, "label": "Rester disponible pour la recontacter si des éléments nouveaux apparaissent", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité rassurante pour la victime.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "éléments nouveaux", "victime rassurée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('vuln-personne-troubles-psychiques-errance', '{"slug": "vuln-personne-troubles-psychiques-errance", "title": "Il parle seul et suit les passants sans les toucher", "theme_slug": "personnes-vulnerables", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 4 heures. En centre-ville, vous observez une personne qui parle seule et suit des passants sans les toucher ni les menacer directement, ce comportement ne caractérisant aucune infraction précise mais révélant une personne manifestement en difficulté sur le plan psychique. Cette configuration, où cette vulnérabilité psychique apparente ne s''accompagne d''aucun danger immédiat identifiable, nécessite de solliciter un avis médical plutôt que d''apporter une réponse strictement policière à cette situation de détresse constatée.\n\nCette situation, caractéristique des rencontres avec des personnes en errance manifestant des troubles psychiques apparents sans commettre d''infraction caractérisée, impose une approche empreinte de prudence qui évite de stigmatiser tout en assurant la protection de cette personne et des passants potentiellement inquiétés.\n\nCette configuration nécessite de solliciter un avis médical plutôt qu''une réponse policière, cette exigence restant essentielle pour orienter cette personne vers une prise en charge adaptée à sa vulnérabilité réelle plutôt que vers une réponse répressive inadaptée.", "questions": [{"position": 1, "max_points": 5, "label": "Comment sollicitez-vous un avis médical plutôt qu''une réponse strictement policière face à cette situation ?", "hint": "Cette sollicitation doit rester appropriée, cette exigence restant essentielle pour orienter cette personne vers une prise en charge adaptée à sa vulnérabilité réelle plutôt qu''une réponse répressive inadaptée.", "perfect": "Je sollicite un avis médical pour évaluer l''état de cette personne, cette démarche restant appropriée face à cette vulnérabilité psychique apparente sans infraction caractérisée.\n\nJe reste factuelle sur les éléments observés, cette précision restant utile pour permettre aux services médicaux d''évaluer correctement cette situation.\n\nJe reste attentive à ne pas qualifier cette situation d''infraction en l''absence d''éléments matériels caractérisés, cette réserve restant juridiquement appropriée.\n\nJe reste attentive à assurer une présence rassurante en attendant cette évaluation médicale, cette présence restant utile pour cette personne et les passants potentiellement inquiétés.", "points": [{"position": 1, "label": "Solliciter un avis médical pour évaluer l''état de cette personne", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : orientation médicale appropriée.", "groups": [{"position": 1, "keywords": ["avis médical sollicité", "évaluation demandée", "vulnérabilité reconnue"]}]}, {"position": 2, "label": "Rester factuelle sur les éléments observés", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Précision permettant une évaluation correcte.", "groups": [{"position": 1, "keywords": ["éléments observés", "précision assurée", "évaluation facilitée"]}]}, {"position": 3, "label": "Ne pas qualifier cette situation d''infraction en l''absence d''éléments matériels", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Réserve juridiquement appropriée.", "groups": [{"position": 1, "keywords": ["infraction non qualifiée", "éléments absents", "réserve appliquée"]}]}, {"position": 4, "label": "Assurer une présence rassurante en attendant cette évaluation médicale", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Présence utile pour la personne et les passants.", "groups": [{"position": 1, "keywords": ["présence assurée", "passants rassurés", "personne accompagnée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous les passants potentiellement inquiétés par ce comportement observé ?", "hint": "Cette gestion doit rester rassurante, cette exigence restant essentielle pour apaiser les passants sans stigmatiser cette personne dont le comportement révèle une simple difficulté psychique.", "perfect": "Je reste attentive à rassurer les passants qui pourraient être inquiétés par ce comportement, cette approche restant appropriée sans stigmatiser cette personne en difficulté.\n\nJe reste factuelle dans mes explications aux passants, évitant tout terme stigmatisant qui pourrait aggraver la situation de cette personne.\n\nJe reste attentive à me positionner de manière visible pour rassurer ce public sans pour autant intervenir de manière intrusive auprès de cette personne.\n\nJe reste attentive à évaluer si ce comportement présente un risque réel pour ces passants, cette évaluation restant nécessaire pour ajuster ma réponse si besoin.", "points": [{"position": 1, "label": "Rassurer les passants sans stigmatiser cette personne en difficulté", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : rassurance sans stigmatisation.", "groups": [{"position": 1, "keywords": ["passants rassurés", "stigmatisation évitée", "personne préservée"]}]}, {"position": 2, "label": "Rester factuelle dans ses explications sans terme stigmatisant", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Explications appropriées évitant l''aggravation.", "groups": [{"position": 1, "keywords": ["explications factuelles", "terme approprié", "aggravation évitée"]}]}, {"position": 3, "label": "Se positionner de manière visible sans intervenir de manière intrusive", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Positionnement rassurant sans intrusion.", "groups": [{"position": 1, "keywords": ["positionnement visible", "intrusion évitée", "présence mesurée"]}]}, {"position": 4, "label": "Évaluer si ce comportement présente un risque réel pour ces passants", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Évaluation ajustant la réponse si nécessaire.", "groups": [{"position": 1, "keywords": ["risque évalué", "réponse ajustée", "passants protégés"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment assurez-vous la suite de cette prise en charge une fois l''avis médical obtenu ?", "hint": "Cette suite doit rester adaptée à la décision médicale obtenue, cette exigence restant nécessaire pour orienter cette personne vers la prise en charge la plus appropriée à sa situation réelle.", "perfect": "Je reste attentive à suivre les préconisations des services médicaux sollicités concernant cette personne, cette conformité restant essentielle pour cette prise en charge.\n\nJe reste factuelle sur le déroulement de cette intervention dans mon compte rendu, cette traçabilité restant utile pour la suite de ce dossier.\n\nJe reste attentive à m''assurer que cette personne est effectivement prise en charge par les services compétents avant de quitter les lieux.\n\nJe reste attentive à documenter cette situation pour faciliter une éventuelle intervention future si cette personne est de nouveau rencontrée dans des circonstances similaires.", "points": [{"position": 1, "label": "Suivre les préconisations des services médicaux sollicités", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : conformité à la décision médicale.", "groups": [{"position": 1, "keywords": ["préconisations suivies", "services médicaux", "conformité assurée"]}]}, {"position": 2, "label": "Documenter factuellement le déroulement de cette intervention", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Traçabilité utile pour la suite du dossier.", "groups": [{"position": 1, "keywords": ["intervention documentée", "compte rendu établi", "dossier suivi"]}]}, {"position": 3, "label": "S''assurer que cette personne est effectivement prise en charge avant de partir", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Prise en charge effective vérifiée.", "groups": [{"position": 1, "keywords": ["prise en charge vérifiée", "services compétents", "personne confiée"]}]}, {"position": 4, "label": "Documenter cette situation pour faciliter une intervention future", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Documentation utile pour de futures rencontres.", "groups": [{"position": 1, "keywords": ["situation documentée", "intervention future", "rencontre facilitée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('vuln-personne-sous-tutelle-exploitee', '{"slug": "vuln-personne-sous-tutelle-exploitee", "title": "Un voisin encaisse ses allocations depuis huit mois", "theme_slug": "personnes-vulnerables", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 15 heures. À son domicile, une personne majeure sous tutelle vous révèle qu''un voisin encaisse ses allocations depuis huit mois sous couvert d''amitié, cet abus de faiblesse caractérisé se heurtant à l''attachement manifeste que cette victime porte à cet « ami » qui l''exploite financièrement. Cette configuration, où cette exploitation financière d''un majeur protégé s''accompagne d''un déni de la victime qui refuse de reconnaître la réalité de cette situation, nécessite de caractériser cet abus malgré ce déni de la victime plutôt que de renoncer face à cette difficulté relationnelle.\n\nCette situation, caractéristique des exploitations financières qui peuvent viser les personnes majeures protégées en s''appuyant sur une relation de confiance détournée, impose un travail de caractérisation rigoureux qui ne dépend pas exclusivement de la reconnaissance de la victime elle-même.\n\nCette configuration nécessite de caractériser cet abus malgré ce déni de la victime, cette exigence restant essentielle pour protéger cette personne majeure protégée indépendamment de son propre attachement à cet auteur de cette exploitation.", "questions": [{"position": 1, "max_points": 5, "label": "Comment caractérisez-vous cet abus de faiblesse malgré le déni manifesté par cette victime ?", "hint": "Cette caractérisation doit rester rigoureuse, cette exigence restant essentielle pour établir la réalité de cet abus indépendamment de la reconnaissance ou du déni de la victime elle-même.", "perfect": "Je recueille précisément les éléments matériels de cette exploitation financière, ces éléments objectifs restant essentiels indépendamment du déni de cette victime.\n\nJe reste factuelle sur la chronologie de ces encaissements depuis huit mois, cette précision restant utile pour établir la réalité et la durée de cette exploitation.\n\nJe reste attentive au statut de majeur protégé de cette victime, ce statut restant un élément juridique déterminant de cette caractérisation.\n\nJe reste attentive à solliciter le tuteur ou curateur de cette personne, cette sollicitation restant nécessaire compte tenu de ce statut de protection juridique.", "points": [{"position": 1, "label": "Recueillir précisément les éléments matériels de cette exploitation financière", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : éléments objectifs indépendants du déni.", "groups": [{"position": 1, "keywords": ["éléments matériels", "exploitation caractérisée", "déni contourné"]}]}, {"position": 2, "label": "Établir la chronologie de ces encaissements depuis huit mois", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Réalité et durée de l''exploitation établies.", "groups": [{"position": 1, "keywords": ["chronologie établie", "durée précisée", "encaissements documentés"]}]}, {"position": 3, "label": "Tenir compte du statut de majeur protégé de cette victime", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Élément juridique déterminant de cette caractérisation.", "groups": [{"position": 1, "keywords": ["statut protégé", "élément juridique", "protection reconnue"]}]}, {"position": 4, "label": "Solliciter le tuteur ou curateur de cette personne", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sollicitation nécessaire compte tenu du statut de protection.", "groups": [{"position": 1, "keywords": ["tuteur sollicité", "curateur informé", "protection juridique"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous l''attachement manifeste de cette victime envers cet auteur de l''exploitation ?", "hint": "Cette gestion doit rester délicate, cette exigence restant essentielle pour ne pas brutalement remettre en cause cette relation à laquelle cette victime reste attachée malgré cette exploitation caractérisée.", "perfect": "Je reste attentive à ne pas brutalement disqualifier cette relation à laquelle cette victime reste manifestement attachée, cette délicatesse restant appropriée.\n\nJe reste factuelle en exposant les faits constatés sans porter de jugement sur les sentiments de cette victime envers cet auteur.\n\nJe reste attentive à expliquer à cette victime la différence entre cette relation affective et cette exploitation financière caractérisée qui l''accompagne.\n\nJe reste attentive à respecter le rythme de cette victime dans sa prise de conscience éventuelle de cette situation, cette patience restant appropriée.", "points": [{"position": 1, "label": "Ne pas brutalement disqualifier cette relation à laquelle la victime reste attachée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : délicatesse face à cet attachement.", "groups": [{"position": 1, "keywords": ["relation respectée", "attachement pris en compte", "délicatesse appliquée"]}]}, {"position": 2, "label": "Exposer factuellement les faits sans porter de jugement sur ses sentiments", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Faits exposés sans jugement des sentiments.", "groups": [{"position": 1, "keywords": ["faits exposés", "jugement évité", "sentiments respectés"]}]}, {"position": 3, "label": "Expliquer la différence entre relation affective et exploitation financière", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Distinction pédagogique pour la victime.", "groups": [{"position": 1, "keywords": ["différence expliquée", "exploitation distinguée", "relation clarifiée"]}]}, {"position": 4, "label": "Respecter le rythme de la victime dans sa prise de conscience", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Patience appropriée face à cette prise de conscience.", "groups": [{"position": 1, "keywords": ["rythme respecté", "patience appliquée", "prise de conscience"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment assurez-vous la protection durable de cette personne majeure protégée au-delà de ce signalement immédiat ?", "hint": "Cette protection durable doit rester organisée, cette exigence restant essentielle pour éviter que cette exploitation ne se poursuive une fois cette intervention terminée.", "perfect": "Je transmets ce signalement aux autorités compétentes en matière de protection des majeurs, cette transmission restant essentielle pour cette protection durable.\n\nJe reste factuelle sur les mesures de protection déjà en place pour cette personne, cette vérification restant utile pour évaluer leur suffisance face à cette exploitation constatée.\n\nJe reste attentive à alerter le tuteur ou curateur des faits constatés, cette information restant nécessaire pour qu''une action appropriée soit engagée.\n\nJe reste disponible pour assurer un suivi de cette situation, cette disponibilité restant utile pour m''assurer que cette exploitation a effectivement cessé.", "points": [{"position": 1, "label": "Transmettre ce signalement aux autorités compétentes en protection des majeurs", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : protection durable assurée.", "groups": [{"position": 1, "keywords": ["signalement transmis", "autorités compétentes", "protection assurée"]}]}, {"position": 2, "label": "Vérifier les mesures de protection déjà en place pour cette personne", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Suffisance évaluée face à cette exploitation.", "groups": [{"position": 1, "keywords": ["mesures vérifiées", "protection évaluée", "suffisance examinée"]}]}, {"position": 3, "label": "Alerter le tuteur ou curateur des faits constatés", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Action appropriée engagée par le tuteur.", "groups": [{"position": 1, "keywords": ["tuteur alerté", "action engagée", "faits transmis"]}]}, {"position": 4, "label": "Assurer un suivi de cette situation pour s''assurer de la cessation de l''exploitation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Suivi confirmant la cessation de l''exploitation.", "groups": [{"position": 1, "keywords": ["suivi assuré", "exploitation cessée", "situation confirmée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('vuln-victime-ne-sachant-pas-lire', '{"slug": "vuln-victime-ne-sachant-pas-lire", "title": "Il signe sans pouvoir relire ce qu''il a déclaré", "theme_slug": "personnes-vulnerables", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 14 heures. Au commissariat, vous recueillez la déclaration d''une victime qui s''apprête à signer ce document sans pouvoir le relire personnellement compte tenu de son illettrisme, cette situation posant une question à la fois de validité et de loyauté de cet acte ainsi que de dignité de cette personne. Cette configuration, où cet illettrisme constaté au moment précis de cette signature ne doit pas être source d''humiliation pour cette personne, nécessite de faire relire ce document à voix haute et de vous assurer de sa compréhension effective avant toute signature définitive.\n\nCette situation, caractéristique des difficultés que peut rencontrer une personne illettrée face à un acte administratif ou procédural nécessitant sa signature, impose une vigilance particulière qui garantisse la validité de cet acte sans stigmatiser cette personne pour cette difficulté rencontrée.\n\nCette configuration nécessite de faire relire ce document à voix haute et de s''assurer de sa compréhension, cette double exigence restant essentielle pour garantir la loyauté de cet acte tout en préservant la dignité de cette personne illettrée.", "questions": [{"position": 1, "max_points": 5, "label": "Comment faites-vous relire ce document à voix haute pour vous assurer de sa compréhension par cette personne ?", "hint": "Cette relecture doit rester systématique, cette exigence restant essentielle pour garantir que cette personne comprend effectivement le contenu de cette déclaration avant de la signer.", "perfect": "Je relis intégralement cette déclaration à voix haute avant toute signature, cette relecture restant essentielle pour garantir la compréhension effective de cette personne.\n\nJe reste factuelle et claire dans cette lecture, cette clarté restant utile pour faciliter la compréhension de cette personne illettrée.\n\nJe reste attentive à m''assurer, au fil de cette lecture, que cette personne comprend bien chaque élément qui lui est présenté.\n\nJe reste attentive à reformuler si nécessaire les termes qui pourraient ne pas être compris par cette personne, cette adaptation restant appropriée.", "points": [{"position": 1, "label": "Relire intégralement cette déclaration à voix haute avant signature", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : compréhension effective garantie.", "groups": [{"position": 1, "keywords": ["déclaration relue", "compréhension garantie", "relecture effectuée"]}]}, {"position": 2, "label": "Rester factuelle et claire dans cette lecture", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Clarté facilitant la compréhension.", "groups": [{"position": 1, "keywords": ["lecture claire", "compréhension facilitée", "clarté appliquée"]}]}, {"position": 3, "label": "S''assurer, au fil de la lecture, de la compréhension de chaque élément", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vérification continue de la compréhension.", "groups": [{"position": 1, "keywords": ["compréhension vérifiée", "éléments confirmés", "lecture suivie"]}]}, {"position": 4, "label": "Reformuler si nécessaire les termes non compris", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Adaptation appropriée du vocabulaire.", "groups": [{"position": 1, "keywords": ["termes reformulés", "vocabulaire adapté", "compréhension assurée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment préservez-vous la dignité de cette personne face à cette difficulté d''illettrisme constatée ?", "hint": "Cette préservation doit rester constante, cette exigence restant essentielle pour ne pas humilier cette personne à l''occasion de cette difficulté d''illettrisme révélée au moment de cette signature.", "perfect": "Je reste attentive à ne manifester aucune surprise ni jugement face à cet illettrisme constaté, cette neutralité restant essentielle pour préserver sa dignité.\n\nJe reste factuelle et naturelle dans ma proposition de relecture, présentant cette démarche comme une pratique habituelle plutôt qu''une adaptation exceptionnelle.\n\nJe reste attentive à ne pas évoquer cette difficulté devant d''autres personnes présentes, cette discrétion restant appropriée pour préserver son intimité.\n\nJe reste attentive à valoriser sa démarche de signalement malgré cette difficulté rencontrée, cette valorisation restant utile pour cette personne.", "points": [{"position": 1, "label": "Ne manifester aucune surprise ni jugement face à cet illettrisme", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : neutralité préservant la dignité.", "groups": [{"position": 1, "keywords": ["neutralité maintenue", "dignité préservée", "jugement absent"]}]}, {"position": 2, "label": "Présenter cette relecture comme une pratique habituelle", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Démarche normalisée plutôt qu''exceptionnelle.", "groups": [{"position": 1, "keywords": ["pratique habituelle", "démarche normalisée", "adaptation discrète"]}]}, {"position": 3, "label": "Ne pas évoquer cette difficulté devant d''autres personnes présentes", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Discrétion préservant son intimité.", "groups": [{"position": 1, "keywords": ["difficulté non évoquée", "intimité préservée", "discrétion appliquée"]}]}, {"position": 4, "label": "Valoriser sa démarche de signalement malgré cette difficulté", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Valorisation utile pour cette personne.", "groups": [{"position": 1, "keywords": ["démarche valorisée", "signalement reconnu", "difficulté surmontée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment garantissez-vous la validité juridique de cet acte compte tenu de cette situation d''illettrisme ?", "hint": "Cette validité doit rester incontestable, cette exigence restant essentielle pour que cet acte ne puisse être remis en cause ultérieurement du fait de cette situation d''illettrisme non prise en compte.", "perfect": "Je m''assure que cette lecture à voix haute et cette compréhension confirmée sont mentionnées dans les modalités de recueil de cet acte.\n\nJe reste factuelle sur les conditions dans lesquelles cette signature intervient, cette précision restant utile pour garantir la validité juridique de cet acte.\n\nJe reste attentive à recueillir une confirmation explicite de sa compréhension avant cette signature définitive.\n\nJe reste attentive à proposer, si les moyens du service le permettent, une assistance renforcée pour les prochaines démarches de cette personne.", "points": [{"position": 1, "label": "Mentionner cette lecture à voix haute et cette compréhension confirmée dans l''acte", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : validité juridique garantie.", "groups": [{"position": 1, "keywords": ["lecture mentionnée", "compréhension confirmée", "acte sécurisé"]}]}, {"position": 2, "label": "Rester factuelle sur les conditions de cette signature", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Précision garantissant la validité juridique.", "groups": [{"position": 1, "keywords": ["conditions précisées", "validité garantie", "signature encadrée"]}]}, {"position": 3, "label": "Recueillir une confirmation explicite de sa compréhension avant signature", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Confirmation explicite avant signature définitive.", "groups": [{"position": 1, "keywords": ["confirmation recueillie", "compréhension explicite", "signature validée"]}]}, {"position": 4, "label": "Proposer une assistance renforcée pour les prochaines démarches", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Assistance future proposée si les moyens le permettent.", "groups": [{"position": 1, "keywords": ["assistance proposée", "démarches futures", "moyens disponibles"]}]}]}]}'::jsonb);